  minor: { icon: AlertTriangle, badge: "bg-amber-500", text: "text-amber-700", bg: "bg-amber-50", border: "border-amber-100", accent: "border-amber-400", label: "Needs improvement" },
  clarify: { icon: Info, badge: "bg-sky-500", text: "text-sky-700", bg: "bg-sky-50", border: "border-sky-100", accent: "border-sky-400", label: "Idea" },
